                penaltyMap.put(p, value + 1);
            }
        }

        int penaltyCount = 0;
        for (int num : collectSet) {
            penaltyCount += penaltyMap.getOrDefault(num, 0);
        }

        System.out.println(collectSet.size() + " " + penaltyCount);
    }

}

