public class Main {

	public static void main(String[] args) throws Exception {
		new Main().run();
	}

	TreeSet<String> ts;

	public void run() throws Exception {
		FastIO file = new FastIO();
		ts = new TreeSet<>();
		permute("ABCDE".toCharArray(), 0);
		int[] a = new int[5];
		for(int i = 0; i < 5; i++) {
			a[i] = file.nextInt();
		}
		int ans = Integer.MAX_VALUE;
		for (String s : ts) {
			int time = 0;
			for (char c : s.toCharArray()) {
				if (time % 10 != 0) {
					time += 10 - time % 10;
				}
				time += a[c - 'A'];
			}
			ans = Math.min(ans, time);
		}
		System.out.println(ans);
	}

	void permute(char[] c, int x) {
		if (x == 5) {
			ts.add(String.valueOf(c));
		}
		else {
			for (int i = 0; i < 5; i++) {
				if (i != x) {
					char temp = c[i];
					c[i] = c[x];
					c[x] = temp;
					permute(c.clone(), x + 1);
					temp = c[i];
					c[i] = c[x];
					c[x] = temp;
				}
			}
		}
	}
	public static class FastIO {
		BufferedReader br;
		StringTokenizer st;

		public FastIO() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreElements()) {
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					e.printStackTrace();
				}
			}
			return st.nextToken();
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		long nextLong() {
			return Long.parseLong(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			String str = "";
			try {
				str = br.readLine();
			} catch (IOException e) {
				e.printStackTrace();
			}
			return str;
		}
	}

	public static long pow(long n, long p, long mod) {
		if (p == 0)
			return 1;
		if (p == 1)
			return n % mod;
		if (p % 2 == 0) {
			long temp = pow(n, p / 2, mod);
			return (temp * temp) % mod;
		} else {
			long temp = pow(n, p / 2, mod);
			temp = (temp * temp) % mod;
			return (temp * n) % mod;

		}
	}

	public static long pow(long n, long p) {
		if (p == 0)
			return 1;
		if (p == 1)
			return n;
		if (p % 2 == 0) {
			long temp = pow(n, p / 2);
			return (temp * temp);
		} else {
			long temp = pow(n, p / 2);
			temp = (temp * temp);
			return (temp * n);

		}
	}

	public static long gcd(long x, long y) {
		if (x == 0)
			return y;
		else
			return gcd(y % x, x);
	}

	public static boolean isPrime(int n) {
		if (n <= 1)
			return false;
		if (n <= 3)
			return true;

		if (n % 2 == 0 || n % 3 == 0)
			return false;

		for (int i = 5; i * i <= n; i = i + 6)
			if (n % i == 0 || n % (i + 2) == 0)
				return false;

		return true;
	}
}

