        public void solve(int testNumber, InputReader in, PrintWriter out) {
            this.out = out;
            this.in = in;
            int n = ni();
            int[] arr = new int[n];
            int i = 0, j = 0;
            for (i = 0; i < n; i++)
                arr[i] = ni();
            int sum = 0;
