        for(int i = 0; i < N; i++) {
            for(int j = 0; j < D; j++) {
                pts[i][j] = scanner.nextInt();
            }
        }
        int ans = 0;
        for(int i = 0; i < N; i++) {
            for(int j = i+1; j < N; j++) {
                int tot = 0;
                for(int k = 0; k < D; k++) {
                    tot += (pts[i][k] - pts[j][k])*(pts[i][k] - pts[j][k]);
                }
                if (square.contains(tot)) ans++;
            }
        }
        out.println(ans);

        out.flush();
    }

