import java.util.Scanner;

class LCM {
    static long lcm(int a, int b){
        return (long)a * b / gcd(a, b);
    }

    private static int gcd(int a, int b){
        if(b == 0){
            return a;
        }else{
            return gcd(b, a % b);
        }
    }
}

public class Main {
    static Scanner stdIn = new Scanner(System.in);
