        for(int i = 0; i<n; i++){
            for(int j = 0; j<m; j++){
                a[i][j] = in.nextDouble();
            }
        }
        int count = 0;
        for(int i = 0; i<n-1; i++){
            double[] t1 = new double[m];
            for(int j = 0; j<m; j++){
                t1[j] = a[i][j];
            }
            for(int j = i+1; j<n; j++){
