		String shuffled_card = ""; // シャッフル後のカードの状態
		int m = 0; // シャッフル回数
		int h = 0; // 下からとる枚数
		int MAX_DATA = 10;
		int NUMBER_OF_DATA = 0;
		String n = ""; // 入力されたカードの山
		boolean judge_m = true; // シャッフル回数が条件を満たしているかを示す変数
		boolean judge_n = true; // 入力されたn枚のカードが条件を満たしているかを示す変数
		String[] output = new String[MAX_DATA];

