		long[] dp = new long [n+k+1];
		Arrays.fill(dp, Long.MAX_VALUE);

		dp[1] = 0;

		for(int i=1;i<=n;i++){
			for(int j=1;j<=k;j++){
				dp[i+j] = Math.min(dp[i+j], Math.abs(h[i+j]-h[i]) + dp[i]);
			}
		}

