        BigInteger ans2=(db.subtract(da));
        BigInteger ans3=(lb.subtract(la));

        BigInteger ans=ans1.add(ans2);
        ans=ans.subtract(ans3);

        BigInteger t=b.subtract(a.subtract(BigInteger.ONE));
        ans=t.subtract(ans);
        System.out.println(ans);







