class FScanner {
	private final InputStream in = System.in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;

	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		} else {
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}

	private int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	private static boolean isPrintableChar(int c) {
		return 33 <= c && c <= 126;
	}

	public boolean hasNext() {
		while (hasNextByte() && !isPrintableChar(buffer[ptr]))
			ptr++;
		return hasNextByte();
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	public long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			} else if (b == -1 || !isPrintableChar(b)) {
				return minus ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}

	public int nextInt() {
		long nl = nextLong();
		if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)
			throw new NumberFormatException();
		return (int) nl;
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }
        bubbleSort(a, n);
        sc.close();
    }

    private static void bubbleSort(int[] a, int n) {
        int exchange = 0;
        boolean flag = true;
        while (flag) {
            flag = false;
            for (int i = n - 1; i > 0; i--) {
                if (a[i] < a[i - 1]) {
                    int ai = a[i];
                    a[i] = a[i - 1];
                    a[i - 1] = ai;
                    exchange++;
                    flag = true;
                }
            }
        }
        print(a, n, exchange);
    }

    private static void print(int[] a, int n, int exchange) {
        String[] aStr = new String[n];
        for (int i = 0; i < n; i++) {
            aStr[i] = String.valueOf(a[i]);
        }
        System.out.println(String.join(" ", aStr));
        System.out.println(exchange);
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);

		//入力
		int amount_btn = sc.nextInt();
		int answer = 1;

		//ボタンの遷移先リスト
		ArrayList<Integer> array_btn = new ArrayList<>();

		for (int i = 0; i < amount_btn; i++) {
			int btn_destination = sc.nextInt();
			array_btn.add(btn_destination);
		}

		//ボタンが使われたかどうかの確認マップ
		Map<Integer, Integer> btn_map = new HashMap<Integer, Integer>();

		//初期値の使われていない状態：0
		for (int i = 0; i <= amount_btn; i++) {
			btn_map.put(i,0);
		}

		int j = 0;

		loop: while(j <= amount_btn) {
			//もしボタンの遷移先が2であれば、終了
			if (array_btn.get(j) == 2) {
				break loop;
			}

			//もしボタンの遷移先が2でなければ、
			else {

				//もしボタンをすでに使用したことがあれば、ループしているので終了
				if (btn_map.get(j) == -1) {
					answer = -1;
					break loop;
				}
				//もしボタン未使用であれば、ボタンを使用した状態にして、次のボタンに遷移
				else {
					btn_map.put(j,-1);
					answer ++;
					j = array_btn.get(j) -1;
				}

			}
		}
		System.out.println(answer);
	}
}

