public class Main {

    static PrintWriter out;
    static Scanner sc;

    static void solve() {
        int[][] c = new int[3][3];
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                c[i][j] = nextInt();
            }
        }

        int[] a = new int[3];
        int[] b = new int[3];

        // a[0]は固定値と想定して問題ない
        a[0] = 0;

        for (int j = 0; j <= 2; j++) {
            b[j] = c[0][j] - a[0];
        }
        for (int i = 1; i <= 2; i++) {
            a[i] = c[i][0] - b[0];
        }

        boolean ok = true;
        for (int i = 1; i <= 2; i++) {
            for (int j = 1; j <= 2; j++) {
                if (c[i][j] != a[i] + b[j]) {
                    ok = false;
                    break;
                }
            }
            if (!ok) {
                break;
            }
        }

        if (ok) {
            out.println("Yes");
        } else {
            out.println("No");
        }
    }

    static int nextInt() {
        return Integer.parseInt(sc.next());
    }

    static long nextLong() {
