            return n * (n - 1) / 2l;
        }

        long ncr(long n, long r) {
            double res = 1.0;
            for (long i = n, j = r; i > (n - r); i--, j--) {
                res *= (i * 1.0) / j;
            }
            return (long) Math.ceil(res);
        }

        long modPow(long x, long y) {
            long res = 1;
            x = x % mod;
            while (y > 0) {
                if (y % 2 != 0)
                    res = pro(res, x);
                x = pro(x, x);
                y = y >> 1;
            }
            return res;
        }

        int gcd(int a, int b) {
            if (b == 0)
                return a;
            return gcd(b, a % b);
        }

        final int maxn = 5005;

        void solve() throws IOException {
            int a = sc.ni();
            int b = sc.ni();
            int c = sc.ni();
            int d = sc.ni();
            int t = 0;
            boolean ans = false;
            while (true) {
                if (t == 0) {
                    c -= b;
                    if (c <= 0) {
                        ans = true;
                        break;
                    }
                } else {
                    a -= d;
                    if (a <= 0)
                        break;
                }
                t = (t + 1) % 2;
            }
            if (ans)
                out.println("Yes");
            else
                out.println("No");
        }
    }
