       String front = str.substring(0,num-1);
       String end = str.substring(num);
       String result = "No"; 

      //文字列を反転　
      StringBuffer sb = new StringBuffer(front);
      String dst = sb.reverse().toString();

       //回文かどうか
       if(dst.equals(end)){
