        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int y = in.nextInt();
            int count10000 = -1;
            int count5000 = -1;
            int count1000 = -1;
            boolean isMatch = false;
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= n; j++) {
                    int yen1000Count = n - i - j;
                    if (yen1000Count >= 0 && 10000 * i + 5000 * j + 1000 * yen1000Count == y) {
