		boolean ans = false;
		if (S.equals(T)) {
			out.println("Yes");
			ans = true;
		}
		else {	

		int  l = S.length();
		for (int i=0; i<l-1; i++){
			String s = S.substring(0, l-1);
			S = S.charAt(l-1)+s;

			if (S.equals(T)){
				out.print("Yes");
