    static class Task {
    	int N, Y;

        void solve(InputReader in, PrintWriter out) {
        	N = in.nextInt();
        	Y = in.nextInt();

        	for (int x = 0; x <= N; ++x) {
        		for (int y = 0; y <= N - x; ++y) {
        			int z = N - (x + y);
        			if (10000*x + 5000*y + 1000*z == Y) {
        				out.println(String.format("%d %d %d", x, y, z));
        				return;
        			}
        		}
        	}

        	out.println("-1 -1 -1");
        }
    }

