public class Main {
  public static String[] str = new String[3];

  public static void main(String[] args) {
    Scanner scn = new Scanner(System.in);

    str[0] = scn.next();
    str[1] = scn.next();
    str[2] = scn.next();

    int num = 0;

    while(num >= 0) {
      num = play(num);
    }

    num += 3;

    switch (num) {
      case 0:
        System.out.println("A");
        break;
      case 1:
        System.out.println("B");
        break;
      case 2:
        System.out.println("C");
        break;
      default:
        break;
    }
