			hm.put(val,1);
		else hm.put(val, hm.get(val)+1);
	}

	public static void remove(HashMap<Integer,Integer> hm, int val){
		hm.put(val, hm.get(val)-1);
		if(hm.get(val)==0){
			hm.remove(val);
		}
