   static class BTAKOYAKIFESTIVAL2019 {
      public void solve(int testNumber, InputReader in, OutputWriter out) {
         int n = in.nextInt();
         int d[] = in.nextIntArray(n);
         int sum = 0;
         for (int x = 0; x < n - 1; x++) {
