    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
        	int n = in.nextInt();
        	int a[] = new int [n];
        	for (int i = 0; i < a.length; i++) {
        		a[i] = in.nextInt();
        	}

        	int num = 0;
        	boolean flag = true;
        	while (flag) {
        		flag = false;
        		for (int i = a.length - 1; i > 0; i --) {
        			if (a[i] < a[i-1]) {
        				int t = a[i];
        				a[i] = a[i-1];
        				a[i-1] = t;
        				flag = true;
        				num += 1;
        			}
        		}
        	}

        	String s = new String();
        	for (int i = 0; i < a.length; i++) {
        		s = s.concat(Integer.toString(a[i]));
        		if (i + 1 != a.length) s = s.concat(" ");
        	}

        	out.println(s);
        	out.println(num);
        }
    }

