import java.io.*;
import java.util.*;
public class Main{
    public static void main(String[] args) throws IOException{
        BufferedReader bf = 
            new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(bf.readLine());
        String[] str = bf.readLine().split(" ");
        List<Integer> h = new ArrayList<>();
        for(int i = 0; i < N; i++){
            h.add(Integer.parseInt(str[i]));
        }
        System.out.println(count(h));
    }
    public static Integer min(List<Integer> data){
        Integer min = data.get(0);
        for(int i = 1; i < data.size(); i++){
            Integer value = data.get(i);
            if(value < min){
                min = value;
            }
        }
        return min;
    }
    public static int count(List<Integer> data){
        int min = min(data);
        for(int i = 0; i < data.size(); i++){
            Integer value = data.get(i);
            data.set(i, value-min);
        }
        boolean zero = true;
        List<List> a = new ArrayList<>();
        for(int i = 0; i < data.size(); i++){
            int value = data.get(i);
            if(zero && value > 0){
                a.add(new ArrayList<Integer>());
                a.get(a.size()-1).add(value);
                zero = false;
            } else if(!zero){
                if(value > 0){
                    a.get(a.size()-1).add(value);
                } else{
                    zero = true;
                }
            }
        }
        int answer = min;
        for(int i = 0; i < a.size(); i++){
            answer += count(a.get(i));
        }
        return answer;
    }
}

import java.util.*;
import java.util.regex.Pattern;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc=new Scanner(System.in);
        String w=sc.next();
        int cnt=0;
        char c;
        String str;
        String[] str2;
        int i;
        while(true){
            str=sc.next();
            if(str.equals("END_OF_TEXT"))break;
            c=getSymbolInString(str);
            str2=null;
            if(c!='a'){
                str2=str.split(Pattern.quote(String.valueOf(c)),0);
            }else{
                str2=new String[1];
                str2[0]=str;
            }
            for(i=0;i<str2.length;i++){
                if(str2[i].toLowerCase().equals(w))cnt++;
            }
        }
        System.out.println(cnt);
    }

    static char getSymbolInString(String s){
        char c;
        int i;
        for(i=0;i<s.length();i++){
            c=s.toLowerCase().charAt(i);
            if(c<'a'||c>'z')return c;
        }
        return 'a';
    }
}

