public class Main {
	static int[][] array;
	public static void main(String[] args) {
		// r = ???, c = ?即?
		int r, c;
		Scanner sc = new Scanner(System.in);
		r = Integer.parseInt(sc.next());
		c = Integer.parseInt(sc.next());
		r += 1;
		c += 1;
		array = new int[r][c];
		for (int i=0; i < r; i++) {
			for (int j=0; j < c; j++) {
				if (i == r-1) {
					array[i][j] = getCsum(j, i);
				} else if (j == c-1) {
					array[i][j] = getRsum(i, j);
				} else {
					array[i][j] = Integer.parseInt(sc.next());
				}
			}
		}
