			System.out.println(sb);
		}
	}
	static final int getRsum(int num, int cSize) {
		int sum = 0;
		for (int i=0; i < cSize; i++) {
			sum = sum + array[num][i];
		}
		return sum;
	}
	static final int getCsum(int num, int rSize) {
		int sum = 0;
		for (int i=0; i < rSize; i++){
			sum = sum + array[i][num];
		}
		return sum;
	}
}

