        out.close();
    }

    static class C {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            // 入力
            long n = Long.parseLong(in.next());
            long a = (long) Math.sqrt(n);
            while (n % a != 0) {
                --a;
            }

            long b = n / a;
            long ans = a - 1 + b - 1;
            // 出力
            out.println(ans);

        }

    }
}

