    public static void main(String[] args) throws IOException {
        int n = 0;
        int m = 0;

        int l = 0;
        int a = 0;
        int matrix_a[][] = new int[100][100]; //n*m
        int matrix_b[] = new int[100];   //m*1
        int matrix_ans [] = new int[100]; //n*1

