				switch(temp) {
				case "+" :
					num[i-2] = num[i-2] + num[i-1];
					i--;
					break;
				case "-" :
					num[i-2] = num[i-2] - num[i-1];
					i--;
					break;
				case "*" :
					num[i-2] = num[i-2] * num[i-1];
					i--;
					break;

				}
			}
		}
		System.out.println(num[i-1]);
	}

}

