    for(int i=1 ; i<n ; i++) {
      lcmans = lcm(lcmans, a[i]);
    }

    long sum = 0;
    for(int i=0 ; i<n ; i++) {
      sum += lcmans/a[i];
    }

    System.out.println((double)lcmans/sum);
  }

  static long gcd(long a, long b) {
    return (b==0) ? a : gcd(b,a%b);
  }

  static long lcm(long a, long b) {
    return (a*b)/gcd(a,b);
  }
}

