        r = new int[Q];
        for(int i = 0;i < Q;i++) {
            l[i] = nextInt();
            r[i] = nextInt();
        }

        int[] sum = new int[N + 1];
        for(int i = 0;i < N;i++) {
            int add = 0;
            if (i + 1 < N) {
                add = S.charAt(i) == 'A' && S.charAt(i + 1) == 'C' ? 1 : 0;
            }
            sum[i + 1] += sum[i] + add;
        }

        for(int i = 0;i < Q;i++) {
            out.println(sum[r[i] - 1] - sum[l[i] - 1]);
        }
    }

    public static void main(String[] args) {
        out.flush();
        new Main().solve();
        out.close();
    }

