            kouho2 *= kouho1;
            kouho1 = x;
        } else if (kouho1 * x >= standard) {
            kouho2 *= x;
        }  else {
            kouho1 *= x;
        }

        System.out.println(Math.max(String.valueOf(kouho1).length(), String.valueOf(kouho2).length()));
    }
}

