class Solver {
    public void solve(long W, long H, long x, long y) {
        final double area = W * H / 2.0;
        final int multiple = W == (x + x) && H == (y + y) ? 1 : 0;

        System.out.println(String.format("%f %d\n", area, multiple));
    }
}

