public class Main
{
	public static void main (String[] args) throws java.lang.Exception
	{
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		InputReader in = new InputReader(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskC solver = new TaskC();
		solver.solve(1, in, out);

		out.close();
	}

	static class TaskC
	{
		void solve(int TestCase, InputReader in, PrintWriter out)
		{
			int n = in.nextInt();
			int[] data = new int[n];
			for(int i = 0; i < n; i++)
			{
				data[i] = in.nextInt();
			}

			int start = 0;
			int ans = 0;
			for(int i = 1; i < n; i++)
			{
				if(data[i] > data[i - 1]) start = i;
				ans = Math.max(ans, i - start);
			}

			out.println(ans);
		}
	}

	static class InputReader
	{
		public BufferedReader reader;
		public StringTokenizer tokenizer;

		public InputReader(InputStream stream)
		{
			reader = new BufferedReader(new InputStreamReader(stream), 32768);
			tokenizer = null;
		}

		public String next()
		{
			while(tokenizer == null || !tokenizer.hasMoreTokens())
			{
				try
				{
					tokenizer = new StringTokenizer(reader.readLine());
				}
				catch(IOException e)
				{
					throw new RuntimeException(e);
				}
			}

			return tokenizer.nextToken();
		}

		public int nextInt()
		{
			return Integer.parseInt(next());
		}
	}
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int N = in.nextInt();
        int D = in.nextInt();
        double[][] arr = new double[N][D];
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < D; ++j) {
                arr[i][j] = in.nextDouble();
            }
        }

        int ans = 0;
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < i; ++j) {
                if (integerDistance(arr[i], arr[j])) 
                    ++ans;
            }
        }

        System.out.println(ans);
    }

    private static boolean integerDistance(double[] a, double[] b) {
        // a & b guaranteed to have same length
        double dist = 0;
        for (int i = 0; i < a.length && i < b.length; ++i) {
            dist += sq(a[i] - b[i]);
        }
        return isInteger(dist);
    }

    private static boolean isInteger(double d) {
        double sqrt = Math.floor(Math.sqrt(d));
        return sqrt * sqrt == d;
    }

    private static double sq(double a) {
        return a * a;
    }
}

