        int[] field = new int[n];

        for(i=0;i<n;i++)
            field[i] = sc.nextInt();

        int[] dp = new int[n+k+1];

        for(i=0;i<n;i++)
            dp[i]=Integer.MAX_VALUE;

        dp[0] = 0;
        for(i=0;i<n-1;i++){
            for(j=i+1;j<=Math.min(n-1,i+k);j++){
                dp[j]=Math.min(dp[j],dp[i] + Math.abs(field[i]-field[j]));
            }
        }

        print(dp[n-1]);
    }

    private static void print(Object o) {
        System.out.println(o.toString());
    }

    private static long lcm(long m, long n) {
        return m * n / gcd(m, n);
    }

    private static long gcd(long m, long n) {
        if(m < n) return gcd(n, m);
        if(n == 0) return m;
        return gcd(n, m % n);
    }

    private static class Pair {
        private int key;
        private int value;

        public Pair(int key, int value){
            this.key=key;
            this.value=value;
        }

        public int getValue(){
            return this.value;
        }

        public int getKey(){
            return this.key;
        }

        public void setValue(int value){
            this.value = value;
        }
    }
}

