  public static class Solver {
    public Solver() {

      int N = sc.nextInt();

      CountMap<String> map = new CountMap<String>(0);
      for (int i=0; i<N; i++) {
        String s = sc.next();
        map.add(s, 1);
      }

      long max = 0;
      for (String s: map.keySet()) {
        max = Math.max(max, map.get(s));
      }

      ArrayList<String> list = new ArrayList<String>();
      for (String s: map.keySet()) {
        if (map.get(s) == max) {
          list.add(s);
        }
      }

      Collections.sort(list);

      for (String s: list) {
        out.println(s);
      }

    }

    public class CountMap<K> extends HashMap<K, Long> {

      long initVal;

      public CountMap(long initVal) {
        super();
        this.initVal = initVal;
      }

      public long g(K key) {
        if (containsKey(key)) {
          return get(key);
        } else {
          return initVal;
        }
      }

      public void add(K key, long value) {
        if (containsKey(key)) {
          put(key, get(key) + value);
        } else {
          put(key, initVal + value);
        }
        if (get(key) == initVal) {
          remove(key);
        }
      }

      public void sub(K key, long value) {
        if (containsKey(key)) {
          put(key, get(key) - value);
        } else {
          put(key, initVal - value);
        }
        if (get(key) == initVal) {
          remove(key);
        }
      }

      public void mul(K key, long value) {
        if (containsKey(key)) {
          put(key, get(key) * value);
        } else {
          put(key, initVal * value);
        }
        if (get(key) == initVal) {
          remove(key);
        }
      }

      public void div(K key, long value) {
        if (containsKey(key)) {
          put(key, get(key) / value);
        } else {
          put(key, initVal / value);
        }
      }

    }
  }

