		FastScanner sc = new FastScanner();
		PrintWriter pw = new PrintWriter(System.out);
		int N = sc.ni();
		ArrayList<Integer> nums = new ArrayList<Integer>(N);
		for (int i = 0; i < N; i++)
			nums.add(sc.ni());
