public class Main {
    public void exec() throws IOException {
        InputUtil input = new InputUtil();
        PrintWriter out = new PrintWriter(System.out);
        while(true) {
            int H = input.nextInt();
            int W = input.nextInt();
            if(H==0 && W==0) break;
            for(int y=0; y<H; y++) {
            	char[] cbuf = new char[W];
            	if(y==0 || y==H-1){
                	Arrays.fill(cbuf, '#');
