		System.out.println();
	}
	static void swap(long[] l, int a, int b) {
		l[a] += l[b];
		l[b]  = l[a] - l[b];
		l[a] -= l[b];
	}
	static void reverse(long[] b) {
		for (int c = 0; c < b.length / 2; c++) {
			swap(b, c, b.length - 1 - c);
		}
	}

}

