public class Main {

	static class Task {
        public void solve(InputReader in, PrintWriter out) {
        	int n = in.nextInt();
        	if(n==1) {
        		out.println(in.nextInt());
        		return;
        	}
        	int ans = 0;
        	int prev = in.nextInt();
        	for(int i=1; i<n; i++) {
        		int curr = in.nextInt();
        		if(prev > curr)
        			ans+=prev-curr;
        		if(i==n-1)
        			ans+=curr;
        		prev = curr;
        	}
        	out.println(ans);
        }

        public void solve_again(InputReader in, PrintWriter out) {
        	int n = in.nextInt();
        	int curr = in.nextInt();
        	int ans = curr;
        	for(int i=1; i<n; i++) {
        		int next = in.nextInt();
        		if(next > curr)
        			ans+=next-curr;
        		curr = next;
        	}
        	out.println(ans);
        }

    }

