    private static void solve(FastScanner in, PrintWriter out){
        int n = in.nextInt();
        int a[] = new int[n];
        int l=100000,r=0;
        for(int i=0;i<n;i++){
            a[i] = in.nextInt();
            l = Math.min(l,a[i]);
            r = Math.max(r,a[i]);
        }
        long sum=0L,ans = Integer.MAX_VALUE;
        for(int i=l;i<=r;i++){
            sum=0;
            for(int j:a){
                sum+=(j-i)*(j-i);
            }
            ans = Math.min(ans,sum);
        }
        out.println(ans);
    }

