        int remain = dish % 10 > 0 ? 10 - (dish % 10) : 0;
        maxRemain = Math.max(maxRemain, remain);
        sum += dish + remain;
      }

      sum -= maxRemain;

      System.out.println(sum);
    }
  }
}

