public class Main{
    public static void main(String args[]) throws IOException {


        Reader sc = new Reader();
        //int t = sc.nextInt();
        int testcase=0,i=0,j=0,k=0;
        int a = sc.nextInt();
        int b  = sc.nextInt();
        int c = sc.nextInt();
        a^=b;
