		int max = (a < b) ? b : a;
		int answer = -1;

		for(int i = 0;i < max;i++) {
			if(Math.abs(a - i) == Math.abs(b - i)) {
				answer = Math.abs(i);
				break;
			}
		}

		System.out.println(answer == -1 ? "IMPOSSIBLE" : answer);

	}
}

