    public static double dis(int a[],int b[]){
        int n = a.length;
        double ans=0.0;
        for(int i=0;i<n;i++){
            ans += Math.pow(a[i]-b[i],2);
        }
        return Math.sqrt(ans);
    }
    private static void solve(FastScanner in, PrintWriter out){
        int n = in.nextInt();
        int d = in.nextInt();
        int p[][] = new int[n][d];
        for(int i=0;i<n;i++){
            for(int j=0;j<d;j++){
