	public static void main(String args[]) {
		int n=scn.nextInt(),k=scn.nextInt();
		int arr[]=new int[n];
		for(int i=0;i<n;i++)
		{
			arr[i]=scn.nextInt();
		}

		if(k>=n)
			System.out.println(Math.abs(arr[n-1]-arr[0]));
		else
		{
