		boolean[] mass = new boolean[N+1];
		for (int i = 0; i < M; i++) {
			mass[sc.nextInt()] = true;
		}
		int ans = 0;
		for (int i = X; i <= N; i++) {
			if (mass[i]) ans++;
		}
		int count = 0;
		for (int i = X; i > 0; i--) {
