            int[] digits = ArrayUtils.convertCharArrayToIntArray(in.readCharArray(4));
            int first = digits[0] * 10 + digits[1];
            int second = digits[2] * 10 + digits[3];
            if (isMonth(first) && isMonth(second)) {
