	public static int gcd(int a,int b,int c) {
		int d=0;
		int ans=0;
		while(d==0) {
		if(a>b) {
			a=a-b;
		}
		else if(a<b) {
			b=b-a;
		}
		else {
			d=a;
		}
		}
		while(ans==0) {
		if(d<c) {
			c=c-d;
		}
		else if(d>c) {
			d=d-c;
		}
		else {
			ans=d;
		}
		}
		return ans;
	}
