      for(int i = 0; i < n; i++){
        String[] row = br.readLine().split(" ");

        for(int j = 0; j < m; j++){
          int value = Integer.parseInt(row[j]);
          if(value < 0 || value > 1000) return;
          matrix1[i][j] = value;
        }
      }
      // input matrix2
      for(int j = 0; j < m; j++){
