  private int[] id;
  public Solution(int n, int[] num) {
    size = new int[n];
    id = new int[n];
    for(int i = 0; i<n; ++i) {
      id[i] = i;
      size[i] = 1;
    }
    for(int i = 1; i < n; ++i) {
      int p = i;
      id[p] = num[i - 1] - 1;
      size[id[p]] += size[p];
    }
