                res = (res * a) % mod;
            }
            a = (a * a) % mod;
            x /= 2;
        }
        return res;
    }

    static long modInverse(long a) {
        return power(a, mod - 2);
    }

    static long nck(long n, long k) {
        long numerator = 1;
        for (int i = 0; i < k; i++) {
            numerator = (numerator * (n - i)) % mod;
        }

        long denominator = 1;
        for (int i = 1; i <= k; i++) {
            denominator = (denominator * i) % mod;
        }
        return (numerator * modInverse(denominator)) % mod;
    }
