    FastScanner in;
    PrintWriter out;

    public void solve() {
        String s = in.next();
        String t = in.next();
        int res = t.length();
        for (int i = 0; i < s.length(); i++) {
            for (int j = i + 1; j <= s.length(); j++) {
                String u = s.substring(i, j);
                if (u.length() != t.length()) continue;

                int cnt = 0;
                for (int k = 0; k < u.length(); k++) {
