	public Solution () {
		reader = new Reader();
		while (reader.hasNext()) {
			run_case();
		}
	}
	private void run_case() {
		int N = ni();
		// System.out.println("N = " + N);
		int res = (int)Math.ceil(1.0 * N / 2);
		System.out.println(res);
		return;
	}
	private int ni() {return Integer.parseInt(reader.next());}
