        char[][] chars = new char[N][10];
        for (int i = 0; i < N; i++) {
            chars[i] = sc.next().toCharArray();
        }
        for (char[] cs : chars) {
            Arrays.sort(cs);
        }
        String[] s = new String[N + 1];
        for (int i = 0; i < N; i++) {
            s[i] = String.copyValueOf(chars[i]);
        }
        s[N] = "{{{{{{{{{{";
        Arrays.sort(s);
        long ans = 0;
        long cnt = 1;
        for (int i = 0; i < N; i++) {
            if (s[i + 1].equals(s[i])) {
                cnt++;
            } else {
                ans += cnt * (cnt - 1) / 2;
                cnt = 1;
            }
        }
        out.println(ans);
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
