    static class Task {
        public void solve(int testNumber, InputReader in, PrintWriter out) throws IOException {
            int n = in.nextInt();
            int[] arr = new int[n];
            int min = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            for (int i = 0; i < n; i++) {
                arr[i] = in.nextInt();
                if (arr[i] > max){
                    max = arr[i];
                }
                if (arr[i] < min){
                    min = arr[i];
                }
            }
            int sum = 0;
            int pos = 0;
            int min_sum = Integer.MAX_VALUE;
            for (int j = min; j <= max; j++) {
                sum = 0;
                for (int i = 0; i < n; i++) {
                    sum += Math.pow(arr[i] - j, 2);
                }
                if (sum < min_sum){
                    min_sum = sum;
                }
            }
            out.println(min_sum);
        }
    }

