             a=Math.abs(arr[index+1]-arr[index])+getAns(arr,index+1,n);
          if(index+2<=n)
            b=Math.abs(arr[index+2]-arr[index])+getAns(arr,index+2,n);
          return dp[index]=Math.min(a,b);
      }
