    static class CTypicalStairs {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            long mod = 10000_0000_7;
            long dp[] = new long[n + 1];
            dp[0] = 1;
            HashSet<Integer> hs = new HashSet<>();
