            if (!hs.contains(1)) dp[1] = 1;
            for (int i = 2; i <= n; i++) if (!hs.contains(i)) dp[i] = (dp[i] + dp[i - 1] + dp[i - 2] + mod) % mod;
            out.println(dp[n]);
        }

    }

