public class Main {

	public static void main(String[] args) {

		FastScanner sc = new FastScanner();
		int N = sc.nextInt();
		int[][] A = new int[3][N + 1];
		for (int i = 1; i <= N; i++)
			A[1][i] = sc.nextInt();
		for (int i = 1; i <= N; i++)
			A[2][i] = sc.nextInt();

		int max = 0;
		for (int i = 1; i <= N; i++) {
			int s = 0;
			for (int j = 1; j <= i; j++)
				s += A[1][j];
			for (int k = i; k <= N; k++)
				s += A[2][k];
			max = Math.max(max, s);
		}

		System.out.println(max);
	}
	//以下、自作ライブラリ

	//最大公約数
	public static long gcd(long a, long b) {
		if (a < b)
			return gcd(b, a);
		long c = 0;
		c = a % b;
		if (c == 0)
			return b;
		return gcd(b, c);
	}

	//最小公倍数
	public static long lcm(long m, long n) {
		return m * n / gcd(m, n);
	}

	//素数判定
	public static boolean isPrime(int n) {
		if (n < 2)
			return false;
		if (n == 2)
			return true;
		if (n % 2 == 0)
			return false;

		for (int i = 3; i * i <= n; i += 2) {
			if (n % i == 0)
				return false;
		}
		return true;
	}
}

