		public void solve(int testNumber, InputReader in, PrintWriter out) {
			int n = in.nextInt();
			int[] x = new int[n];
			for (int i = 0; i < n; i++) {
				x[i] = in.nextInt();
			}
			int ans = Integer.MAX_VALUE;
			for (int i = 1; i <= 100; i++) {
				int count = 0;
				for (int j = 0; j < n; j++) {
