      if(s[i].equals("+")){
        a = stack[j-2];
        b = stack[j-1];
        stack[j-2] = a+b;
        j = j-1;
      }
      else if(s[i].equals("-")){
        a = stack[j-2];
        b = stack[j-1];
        stack[j-2] = a-b;
        j = j-1;
      }
      else if(s[i].equals("*")){
        a = stack[j-2];
        b = stack[j-1];
        stack[j-2] = a*b;
        j = j-1;
      }
      else{
        a = Integer.parseInt(s[i]);
        stack[j] = a;
        j=j+1;
      }
    }
    System.out.println(stack[0]);
  }
}

