    private static void solve(int q, FastScanner in, PrintWriter out) {
        for (int qq = 0; qq < q; qq++) {
            String s = in.next(), t = in.next();
            int best = t.length();

            int diff = 0, m = t.length(), n = s.length();
            for(int i = 0; i <= n - m; i++) {
                diff = 0;
                for(int j = 0; j < m; j++) {
                    if(t.charAt(j) != s.charAt(j + i)) {
                        diff++;
                    }
                }
                best = Math.min(best, diff);
            }
            out.println(best);
        }
