      else if(rating <= 1599)
        color = "cyan";
      else if(rating <= 1999)
        color = "blue";
      else if(rating <= 2399)
        color = "yellow";
      else if(rating <= 2799)
        color = "orange";
      else if(rating <= 3199)
        color = "red";
      else {
        highs++;
      }
      if(color.length() > 0) {
        if(!list.contains(color))
          list.add(color);
      }
