    static class AFerrisWheel {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int i, j;
            int a = in.ni();
            int b = in.ni();
            int ans = 0;
            if (a >= 13)
                ans = b;
            else if (a >= 6 && a <= 12)
                ans = b / 2;
            out.println(ans);
        }

