		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		long cnt = 0, ans = 0;
		String s[] = new String[n];
		for (int i = 0; i < n; ++i) {
			s[i] = sc.next();
			String tm = mysort(s[i]);
			s[i] = tm;
		}
		sc.close();
		Arrays.sort(s);
		String t = s[0];
		for (int i = 0; i < n; ++i) {
			if (t.equals(s[i]))
				++cnt;
			else {
				t = s[i];
				ans += calc(cnt);
				cnt = 1;
			}
		}
		ans += calc(cnt);
		System.out.println(ans);
	}
}

