	PrintWriter out;
    public Solver(InputStream in, PrintWriter out) {
    	sc = new Scanner(in);
    	this.out = out;
    }
    // ==================================================================
    public void solve() {
    	int N = ni();
    	int Y = ni();
    	for (int i = 0; i <= N; i++) {
    		for (int j = 0; j <= N; j++) {
				if((N-i-j) >= 0 &&
					(Y - i*10000 - 5000*j - (N-i-j)*1000) == 0) {
					out.println(i + " " + j + " " + (N-i-j));
