public class Main {

	public static void main(String[] args) {

		FastScanner sc = new FastScanner();
		int N = sc.nextInt();
		int A = sc.nextInt();
		int B = sc.nextInt();
		int ans = 0;
		for (int i = 1; i <= N; i++) {
			if (i / 10 == 0) {
				if (A <= i && i <= B)
					ans += i;
			} else if (i / 100 == 0) {
				if (A <= i % 10 + i / 10 && i % 10 + i / 10 <= B)
					ans += i;
			} else if (i / 1000 == 0) {
				if (A <= i % 10 + i % 100 / 10 + i / 100 && i % 10 + i % 100 / 10 + i / 100 <= B)
					ans += i;
			} else if (i / 10000 == 0) {
				if (A <= i % 10 + i % 100 / 10 + i % 1000 / 100 + i / 1000
						&& i % 10 + i % 100 / 10 + i % 1000 / 100 + i / 1000 <= B)
					ans += i;
			} else if (i == 10000) {
				if (A <= 1 && 1 <= B)
					ans += i;
			}
		}
		System.out.println(ans);

	}
	//以下、自作ライブラリ

	//最大公約数
	public static long gcd(long a, long b) {
		if (a < b)
			return gcd(b, a);
		long c = 0;
		c = a % b;
		if (c == 0)
			return b;
		return gcd(b, c);
	}

	//最小公倍数
	public static long lcm(long m, long n) {
		return m * n / gcd(m, n);
	}

	//素数判定
	public static boolean isPrime(int n) {
		if (n < 2)
			return false;
		if (n == 2)
			return true;
		if (n % 2 == 0)
			return false;

		for (int i = 3; i * i <= n; i += 2) {
			if (n % i == 0)
				return false;
		}
		return true;
	}
}

