		PrintWriter out = new PrintWriter(System.out);

		int n = scan.nextInt();
		int[] w = new int[n];

		int sum = 0;
		for (int i = 0; i < n; i++) {
			int tmp = scan.nextInt();
			w[i] = tmp;
			sum += tmp;
		}

		int ret = 0;
		int half = sum / 2;
		for (int i = 0; i < n; i++) {
			ret += w[i];
			if (ret == half) {
				ret = 0;
				break;
			} else if (ret > half) {
				int a = sum - ret;
				int b = sum - (ret - w[i]);
				ret = Math.min(Math.abs(ret - a), Math.abs((ret - w[i]) - b));
				break;
			}

		}

		out.println(ret);
		out.flush();
	}

