import java.util.Scanner;
public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		String[] W = new String[N];

		for(int i=0; i<N; i++) {
			W[i] = sc.next();
		}

		int judge1 = 0;

		for(int j=0; j<N-1; j++) {
			char c1 = W[j].charAt(W[j].length()-1);
			char c2 = W[j+1].charAt(0);

			if(c1 == c2) {
				judge1 += 1;
			}
		}

		int judge2 = 0;

		for(int k=0; k<N-1; k++) {
			for(int l=1; l<N-k; l++) {
				if(W[k].equals(W[k+l])) {
					judge2 += 1;
				}
			}
		}

		if(judge1 == N-1 && judge2 == 0) {
			System.out.println("Yes");
		}else {
			System.out.println("No");
		}

	}

}

import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int week = sc.nextInt();
		long money = 100000;

		for(int i = 0; i < week; i++){
			money += getInterest(money);
			money = revaliationMoney(money);
		}

		System.out.println(money);
	}

	private static long getInterest(long money){
		return money * 5 / 100;
	}

	private static long revaliationMoney(long money){
		long fraction = money % 1000;
		if(fraction != 0){
			money = money - fraction;
			return money + 1000;
		}
		else{
			return money;
		}
	}
}

import java.util.Scanner;

class Pair {
    String name;
    int time;
}

public class Main {
    static int LEN;
    static int head;
    static int tail;
    static Pair[] pairs;

    // データの追加
    public static void enqueue(Pair x) {
        pairs[tail] = x;
        tail = (tail + 1) % LEN;
    }

    // データを取り出す
    public static Pair dequeue() {
        Pair x = pairs[head];
        head = (head + 1) % LEN;
        return x;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(); // n個のプロセス
        int q = sc.nextInt(); // 最大実行時間
        LEN = 100005;
        pairs = new Pair[LEN];
        for (int i = 1; i <= n; i++) {
            pairs[i] = new Pair();
            pairs[i].name = sc.next();
            pairs[i].time = sc.nextInt();
        }
        head = 1;
        tail = n + 1;
        int now = 0;
        while (tail != head) {
            Pair u = dequeue();
            if (u.time - q > 0) {
                now += q;
                u.time = u.time - q;
                enqueue(u);
            } else {
                now += u.time;
                System.out.println(u.name + " " + now);
            }
        }
        sc.close();
    }

}

