class AtCoder {

    /* 変数宣言 */
    long A, B, K;

    AtCoder(FastScanner sc) {
        A = sc.nextLong();
        B = sc.nextLong();
        K = sc.nextLong();
    }

    void solve(PrintWriter out) {
        if (K >= A) {
            K -= A;
            A = 0;
        } else {
            A -= K;
            K = 0;
        }
        if (K >= B) {
            K -= B;
            B = 0;
        } else {
            B -= K;
            K = 0;
        }
        out.println(A + " " + B);
    }

}

