	static class Task {
		public void solve(int testNumber, InputReader in, PrintWriter out) {
			int N = in.nextInt();
			int[] V = new int[N];
			int[] C = new int[N];
			int total = 0;
			for(int i = 0; i <  N; i++) {
				V[i] = in.nextInt();
			}
			for(int i = 0; i <  N; i++) {
				C[i] = in.nextInt();
				if(V[i] > C[i]) {
					total += V[i] - C[i];
				}
			}
			out.println(total);
		}
	}

