import java.util.Scanner;

class Main {
	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		Long N = Long.parseLong(sc.next());
		Long K = Long.parseLong(sc.next());
		Long J = 0L;

		while(true) {
			if(N/K > 10) {
				J = N;
				N -= (N/K)*K;
			} else {
				J = N;
				N -= K;
			}
			if(Math.abs(J) <= Math.abs(N)) {
				break;
			}
		}
		System.out.println(Math.min(Math.abs(J), Math.abs(N)));
	}
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {

	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		ArrayList<Integer> aEven = new ArrayList<>(); 
		for(int i = 0; i < n; i++) {
			int ai = sc.nextInt();

			if((ai % 2) == 0) {
				aEven.add(ai);
			}
		}

		aEven.sort(null);

		int count = 0;
		System.out.println(operation(aEven, count));


	}

	static int operation(ArrayList<Integer> al, int count) {
		if(al.size() == 0) {
			return count;
		}else {

			int target = al.get(al.size() - 1);
			target = target / 2;
			count++;

			if((target % 2) == 0) {
				al.set(al.size() - 1, target);
			}else {
				al.remove(al.size() - 1);
			}

			count = operation(al, count);

			return count;
		}

	}
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int N = scan.nextInt();
		List<Integer> list = new ArrayList<Integer>();
		for (int i = 0; i < N; i++) {
			list.add(scan.nextInt());
		}
		bubbleSort(list);
	}

	public static void bubbleSort(List<Integer> list) {
		int count = 0;
		for (int i = 1; i < list.size(); i++) {
			int j = i - 1;
			while (j >= 0 && list.get(j + 1) < list.get(j)) {
				int tmp = list.get(j + 1);
				list.set(j + 1, list.get(j));
				list.set(j, tmp);
				j--;
				count++;
			}
		}
		showList(list);
		System.out.println(count);
	}

	public static void showList(List<Integer> list) {
		for (int i = 0; i < list.size() - 1; i++) {
			System.out.print(list.get(i));
			System.out.print(" ");
		}
		System.out.println(list.get(list.size() - 1));
	}
}

