                    ans++;
                } else {
                    penalty[p]++;
                }
            }
            int pen = 0;
            for (int i = 0; i < n; i++) {
                if (ac[i]) pen += penalty[i];
            }
            out.ans(ans).ans(pen).ln();
        }

    }

