        if(isPalindrome(s,0,n-1)) {
            if(isPalindrome(s,0,i-1) && isPalindrome(s,j-1,n-1)) {
                out.println("Yes");
            }
            else {
                out.println("No");
            }
        }
        else {
            out.println("No");
        }
        out.flush();
    }
    private static boolean isPalindrome(String s, int start, int end) {
        int i = start;
        int j = end;
        while (i < j) {
            if(s.charAt(i++)!=s.charAt(j--)) {
                return false;
            }
        }
        return true;
    }
