		else if(e - a > k) return false;
		else if(c - b > k) return false;
		else if(d - b > k) return false;
		else if(e - b > k) return false;
		else if(d - c > k) return false;
		else if(e - c > k) return false;
		else if(e - d > k) return false;
		return true;
	}
}

