    static boolean find(String s) {
        Stack<Character> ch = new Stack<>();
        for (int i = 0; i < s.length(); i++) {
            char ch1 = s.charAt(i);
            if (ch1 == '(') ch.push(ch1);
            else if (ch1 == ')') {
                if (ch.isEmpty() || ch.peek() != '(') return false;
                ch.pop();
            }
