@SuppressWarnings("unchecked")
public class Main {
    public static void main(String[] args) throws IOException {
        PrintWriter out = new PrintWriter(System.out);

        final int N = nextInt();

        int[] h = new int[N];
        int[] after = new int[N];

        for (int i = 0; i < N; i++) {
            h[i] = nextInt();
        }

        boolean[] done = new boolean[N];

        int cnt = 0;

        for (int i = 0; i < N; i++) {
            if (h[i] == 0) {
                done[i] = true;
                cnt++;
            }
        }

        boolean flg = true;

        int ans = 0;

        while (flg) {
            if (cnt == N) break;

            ans++;

            boolean on = false;
            boolean change = false;

            for(int i = 0; i < N; i++) {
                if (!done[i]) {
                    on = true;
                    if (change) {
                        ans++;
                        change = false;
                    }
                    after[i]++;
                    if (after[i] == h[i]) {
                        done[i] = true;
                        cnt++;
                    }
                } else {
                    if (on) {
                        change = true;
                        on = false;
                    }
                }
            }
        }

        out.println(ans);

        out.flush();
    }

