    static class CTaxIncrease {
        public void solve(int testNumber, LightScanner in, LightWriter out) {
            int a = in.ints(), b = in.ints();
            for (int i = 0; i <= 100000; i++) {
                if ((i * 8) / 100 == a && (i * 10) / 100 == b) {
                    out.ans(i).ln();
                    return;
                }
            }
            out.ans(-1).ln();
        }

