	static class TaskX {
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			char[] s = in.nextString().toCharArray();
			String[] t = new String[4];
			t[0] = ("dream");
			t[1] = ("dreamer");
			t[2] = ("erase");
			t[3] = ("eraser");

			int slen = s.length;
			while (slen > 0) {
				boolean isMatch = false;
				for (int k = 0; k < 4; k++) {
					int tlen = t[k].length();
					char[] tar = t[k].toCharArray();
					boolean isSame = true;
					for (int i = slen - tlen; i < slen; i++) {
						if (i < 0) {
							isSame = false;
							break;
						}
						if (s[i] == tar[i - slen + tlen]) {
							continue;
						} else {
							isSame = false;
							break;
						}
					}
					if (isSame) {
						slen -= tlen;
						isMatch = true;
						break;
					}
				}
				if (!isMatch) {
					out.println("NO");
					return;
				}
			}
			out.println("YES");

		}
	}

