                    formula.push(String.valueOf(num1-num2));
                    break;
                case "*":
                    num2 = Integer.parseInt(formula.poll());
                    num1 = Integer.parseInt(formula.poll());
                    formula.push(String.valueOf(num1*num2));
                    break;
                default:
                    formula.push(input);
                    break;
            }
        }
        System.out.println(formula.poll());
    }
}

