		int a = sc.nextInt();
		List<Integer> box = new ArrayList<>();
		int count = 0;

		// 与えられた初期値によってリストを作成
		for (int i = 1; i <= a; i++) {
			box.add(sc.nextInt());
		}
		while (check(box)) {
			box = divide(box);
			count++;
		}
