public class Main {
  private static String solve(int n, int t) {
    t /= 1000;
    for (int x = 0; x <= n; x++) {
      // 5 * y + z = t - 10 * x
      //     y + z = n - x
      // 4 * y = t - 9 * x - n 
      int y4 = t - 9 * x - n;
      if (y4 < 0 || y4 % 4 != 0) {
        continue;
      }
      int y = y4 / 4;
      int z = n - x - y;
      if (z < 0) {
        continue;
      }
      return String.format("%d %d %d", x, y, z);
    }
    return "-1 -1 -1";
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int y = reader.nextInt();
    out.println(solve(n, y));
  }

