			S.add(0, d);
			min = d%10;
		}

		else {
			S.add(1, d);
		}

		if (e%10<min && e%10!=0){
			S.add(0, e);
		}

		else {
			S.add(1, e);
		}

		int temp = S.get(0);
		S.remove(0);

		while (S.isEmpty()!=true){
			int pop = S.pop();
			int rem = pop%10;

			if (rem!=0){
				temp+=(pop-rem+10);

			}
			else temp+=pop;

		}
		System.out.println(temp);

	}

}

