		FastScanner fs = new FastScanner();

		String s = fs.next();

		int index = 0;
		boolean yes = true;

		while(index < s.length()) {
			int retIndex;
			if(s.charAt(index) == 'e') {
				retIndex = checkEraseOrEraser(s, index);
				if(retIndex == -1) {
					yes = false;
					break;
				}
				index = retIndex;
			}else if(s.charAt(index) == 'd') {
				retIndex = checkDreamOrDreamer(s, index);
				if(retIndex == -1) {
					yes = false;
					break;
				}
				index = retIndex;
			}else {
