            for (long i : a)
                ans = Math.max(ans , i);
            return ans;
        }
        public static long power(long x, int y){
            long res = 1;
            while (y > 0)
            {
                if ((y & 1) == 1)
                    res = (res*x);
                y = y >> 1;
                x = x * x;
            }
            return res;
