class AtCoder {

    /* 変数宣言 */
    final int N, K;
    final List<Integer> p;

    AtCoder(FastScanner sc) {
        N = sc.nextInt();
        K = sc.nextInt();

        p = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            p.add(sc.nextInt());
        }
    }

    void solve(PrintWriter out) {
        Collections.sort(p);
        int sum = 0;
        for (int i = 0; i < K; i++) {
            sum += p.get(i);
        }

        out.println(sum);
    }
}
