class AtCoder {

    final String S;

    AtCoder(FastScanner sc) {
        S = sc.next();
    }

    void solve(PrintWriter out) {
        int cnt = 0;
        final int N = S.length();
        for (int i = 0; i < N; i++) {
            if (Integer.parseInt(S.substring(i, i + 1)) == i % 2) cnt++;
        }
        out.println(Math.min(cnt, N - cnt));
    }

}

