            int A = a * a, B = b * b, C = c * c;
            boolean isRight;
            if (A > B && A > C) {
                isRight = A == B + C;
            } else if (B > A && B > C) {
                isRight = B == A + C;
            } else {
                isRight = C == A + B;
            }
            System.out.println(isRight ? "YES" : "NO");
        }
    }
}

