class TaskA {

	public void solve(InputReader in, PrintWriter out) {
		String[] ss = new String[3];
		int[] beg = new int[3];
		int[] sz = new int[3];

		Arrays.fill(beg, 0);
		for (int i=0; i<3; ++i) {
			ss[i] = in.next();
			sz[i] = ss[i].length();
		}

		int cur = 0;

		while (beg[cur] < sz[cur]) {
			int nxt = getId(ss[cur].charAt(beg[cur]));
			beg[cur]++;
			cur = nxt;
		}

		char ans = (char)(cur + 'A');

		out.println(ans);
	}

	private int getId(char ch) {
		return ch - 'a';
	}
}


