        List<String> alp = Arrays.asList("a", "b", "c", "d", "e", "f", "g", "h", "i", "j", "k", "l", "m", "n", "o", "p", "q", "r", "s", "t", "u", "v", "w", "x", "y", "z");
        long n = sc.nextLong();
        int a = 0;
        for (int i = 1; i <= 26; i++) {

            long pow = (long) Math.pow(26, i);
