            if (n <= pow) {
                a = i;
                break;
            } else {
                sub += pow;
            }
            n = n - sub;
        }
        StringBuilder sb = new StringBuilder();

        for (int i = 1; i < a; i++) {
            long pow = (long) Math.pow(26, a - i);
            long sub = 0;
            for (int j = 1; j <= 26; j++) {
                if (n <= pow * j) {
                    sb.append(alp.get(j - 1));
                    break;
                } else {
                    sub += pow;
                }
            }
            n = n - sub;
        }
        sb.append(alp.get((int) (n - 1)));
        System.out.println(sb.toString());
    }
