			hoge-=C;
		if(B>C)
			hoge2=(B/C+1)*C;
		else
			hoge2=C;
		if(C==B)
			hoge2+=C;
		ans-=(hoge2-hoge)/C;ans++;
		//kireme
		if(A>D)
			hoge=(A/D)*D;
		else
			hoge=0;
		if(A%D==0&&A>D)
			hoge-=D;
		if(B>D)
			hoge2=(B/D+1)*D;
		else
			hoge2=D;
		if(D==B)
			hoge2+=D;
		ans-=(hoge2-hoge)/D;ans++;
		//kireme2
		hoge=C;hoge2=D;
		while(hoge%hoge2!=0){
			hoge3=hoge%hoge2;
			hoge=hoge2;
			hoge2=hoge3;
		}
		hoge3=(C*D)/hoge2;
		if(A>hoge3)
			hoge=(A/hoge3)*hoge3;
		else
