        for (int i = 1; i <= n; i++) {
            diff = Math.abs(x[i]-x[i-1]) + Math.abs(y[i]-y[i-1]);
            if (t[i]-t[i-1] >= diff && (t[i]-t[i-1])%2 == diff%2) continue;
            else {
                flag = false;
                break;
            }
        }

        System.out.println(flag?"Yes":"No");
    }
}

