	private static boolean check(int i) {
		if (i % 3 == 0) {
			return true;
		}
		int len = (int) Math.log10(i) + 1;
		int tmp = i;
		for (int j = len - 1; j >= 0; j--) {
			int warikitta = tmp / (int) Math.pow(10, j);
			if (warikitta == 3) {
				return true;
			}
			tmp = tmp - warikitta * (int) Math.pow(10, j);
		}
		return false;
	}
}

