    static class abc135_c {
        public void solve(int testNumber, MyScanner in, PrintWriter out) {
            int N = in.Int();
            int[] A = in.Int(N + 1);
            int[] B = in.Int(N);

            long ans = 0;
            for (int i = 0; i < N; i++) {
                if (A[i] <= B[i]) {
                    ans += A[i];
                    B[i] -= A[i];
                } else {
                    ans += B[i];
                    B[i] = 0;
                }
                int min = Math.min(A[i + 1], B[i]);
                ans += min;
                A[i + 1] -= min;

            }
            out.println(ans);
        }

    }

