                decimal = decimal.multiply(new BigDecimal(val));
                if (decimal.compareTo(max) > 0) {
                    overflow = true;
                }
            }
        }

        if (overflow) {
            System.out.println("-1");
        } else {
            System.out.println(decimal);
        }

    }
}

