	static long power(long x, long y, long p) 
    { 
        long res = 1; 
        x = x % p; 

        while (y > 0) 
        {
            if (y % 2 == 1) 
                res = (res * x) % p; 

            y = y >> 1; 
            x = (x * x) % p; 
        }
        return res; 
    } 
	static long modInverse(long n, long p) 
    { 
        return power(n, p-2, p); 
    }

	static long nCrModPFermat(int n, int r, long p) 
	{ 

		if (r == 0) 
			return 1; 

		return (fact[n]* modInverse(fact[r], p) % p * modInverse(fact[n-r], p) % p) % p; 
	}
