import java.util.Scanner;
public class Main {

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();

		int X = sc.nextInt();

		int sum = 0;

		int min = sc.nextInt();

		int a = 0;

		sum += min;

		int ans = N;

		for(int i=1;i<N;i++) {

			a = sc.nextInt();

