	public static long gcd(long a, long b) {
		long max = Math.max(a, b);
		long min = Math.min(a, b);
		if (max % min == 0)
			return min;
		return gcd(min, max % min);
	}

	public static long lcm(long a, long b, long gcd) {
		return a * b / gcd;
	}
}

