			int left = 0;
			int right = s.size() - 1;
			int mid = (left + right) / 2;
			while(left <= right) {
				if(i.intValue() == s.get(mid).intValue()) {
					count++;
					break;
				} else if (i.intValue() < s.get(mid).intValue()) {
					right = mid - 1;
					mid = (left + right) / 2;
				} else {
					left = mid + 1;
					mid = (left + right) / 2;
				}
			}
		}
		System.out.println(count);
	}
}

