class Main {

	static class InsertionSort {
		public void insertionsort (InputReader ir) {

			int n = ir.nextInt();
			int array[] = new int[n];
			StringBuilder sb = new StringBuilder ();

			//配列入力
			for (int i = 0; i < n; i++ ) {
				array[i] = ir.nextInt();

				if (i != 0) sb.append(" ");
				sb.append(array[i]);
			}

			System.out.println(sb);
			sb.setLength(0);

			//挿入ソート
			for (int i = 1; i < n; i++) {
				int v = array[i];
				int j = i - 1;

				while ( j >= 0 && array[j] > v) {
					array[j + 1] = array[j];
					j--;
				}
				array[j + 1] = v;

				for (int k = 0; k < n; k++ ) {
					if (k != 0) sb.append(" ");
					sb.append(array[k]);
				}
				System.out.println(sb);
				sb.setLength(0);
			}


		}
	}

