    static class ATenki {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            String s1 = in.readLine();
            String s2 = in.readLine();
            int count = 0;
            for (int i = 0; i < s1.length(); i++) {
                if (s1.charAt(i) == s2.charAt(i)) {
                    count++;
                }
            }
            out.printLine(count);
        }

