    public static boolean isPower(int n) {
        if(n == 1) {
            return false;
        } else {
            for(int i = 2; Math.pow(n, 1.0/i) >= 2.0; i++) {
                double d = Math.pow(n, 1.0/i);
                if(d - Math.floor(d) < 0.00001)
                    return true;
            }
        }

        return false;
    }
}

