    int[] num = new int[102];

    for(int i = 0 ; i < 102;i++) {
      num[i] = i;
    }


    for(int i = 0;i < n;i++) {
      num[Integer.parseInt(str2[i])] = -1;
    }
    int minIndex = -1;
    int maxIndex = -1;

    for(int i = 0 ; i < 102;i++) {
      if(i < index) {
        if(num[i] != -1) {
          minIndex = i;
        }
      }else {
        if(num[i] != -1) {
          maxIndex = i;
          break;
        }
      }
    }

    int ans = 0;
    if(minIndex != -1 && maxIndex != -1) {
      if(x - num[minIndex] <= num[maxIndex] - x) {
        ans = num[minIndex];
      }else {
        ans = num[maxIndex];
      }
    }else if(minIndex != -1 && maxIndex == -1) {
      ans = num[minIndex];
    }else {
      ans = num[maxIndex];
    }

    System.out.println(ans);

  }

}

import java.util.*;

class Main {

    //再帰的に1の個数を探すメソッド
    public static int useRecursionToCountChars (String str, char key, int index){
        if (index >= str.length()) {
            return 0;
        }

        //文字列とキーが一致したらcountに1を入れる、そうでなければ0
        int count = str.charAt(index) == key? 1:0;
        //カウントに数を足して再帰処理、インデックスが文字列の長さを超えたらリターン
        return count + useRecursionToCountChars(str,key,index + 1);

    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String str = sc.next();
        int result = useRecursionToCountChars (str,'1', 0);
        System.out.println(result);
    }
}

