		int N = sc.nextInt();
		int M = sc.nextInt();

		// ACとWAの集計
		Set<Integer> ACset = new HashSet<>();
		Map<Integer, Integer> WAmap = new HashMap<>();
		for (int i = 0; i < M; i++) {
			int pi = sc.nextInt();
			String Si = sc.next();
			if (Si.equals("AC")) {
				ACset.add(pi);
			}
