				if (WAmap.containsKey(pi)) {
					int count = WAmap.get(pi) + 1;
					WAmap.put(pi, count);
				}
				else {
					WAmap.put(pi, 1);
				}
			}
		}

		// WAmapのうちACが一度でも出たものだけ集計
		int WAcount = 0;
		for (int key : WAmap.keySet()) {
			if (ACset.contains(key)) {
				WAcount += WAmap.get(key);
			}
		}
		// 結果の出力
		System.out.println(ACset.size() + " " + WAcount);

		sc.close();
	}
}

