class Main {

	public static void main(String[] args) {

		FastScanner sc = new FastScanner();
		final int N = sc.nextInt();

		String[] s = new String[N];
		for (int i = 0; i < N; i++)
			s[i] = sc.next();
		char[] c = new char[10];
		for (int i = 0; i < N; i++) {

			for (int j = 0; j < 10; j++) {

				c[j] = s[i].charAt(j);
			}

			Arrays.sort(c);
			s[i] = String.valueOf(c);

		}
		Arrays.sort(s);
		long ans = 0;
		long count = 0;

		for (int i = 0; i < N - 1; i++) {

			if (s[i].equals(s[i + 1]))
				count++;

