        long divC = divCTop - divCBot;

        long divDTop = b / d;
        long divDBot = (a - 1) / d;
        long divD = divDTop - divDBot;

        long temp = LCM(c, d);
        long divCDTop = b / (temp);
        long divCDBot = (a - 1) / (temp);
