        ArrayList<Integer> list = new ArrayList<>();
        int max = 100003;
        int[] sosu = new int[max];
        //1～10000
        for (int i = 0; i < max; i++) {
            sosu[i] = i+1;
        }
        //1を消す
        sosu[0] = 0;
        //エラトステネス
        for (int i = 1; i < Math.floor(Math.sqrt(max)); i++) {
