	static long Gcd (long c, long d) {
		return c == 0 ? d : Gcd(d % c , c);
	}
	static long Lcm (long c, long d) {
		return c * d / Gcd(c, d);
	}
    static void solve() {
		long A = nl();
		long B = nl();
		long C = nl();
		long D = nl();
		long LcmCD = Lcm(C, D);
		long tot = B - A + 1;

		long divC = A / C;
		if (A % C != 0) divC++;
		if (B - (C * divC) >= 0) tot -= (B - (C * divC)) / C + 1;
		err.println(tot);

		long divD = A / D;
		if (A % D != 0) divD++;
		if (B - (D * divD) >= 0) tot -= (B - (D * divD)) / D + 1;
		err.println(tot + " " + LcmCD);

		long divCD = A / LcmCD;
		if (A % LcmCD != 0) divCD++;
		if (B - (LcmCD * divCD) >= 0) tot += (B - (LcmCD * divCD)) / LcmCD + 1;
		out.println(tot);
    }    

