        Scanner scanner = new Scanner(System.in);
        int N = Integer.parseInt(scanner.next());
        int M = Integer.parseInt(scanner.next());
        int[][] gate = new int[M][2];
        for (int i = 0; i < M; i++) {
            gate[i][0] = Integer.parseInt(scanner.next());
            gate[i][1] = Integer.parseInt(scanner.next());
        }
        scanner.close();


        // 最小レンジを求める
        int min = Integer.MIN_VALUE;
        int max = Integer.MAX_VALUE;
        for (int i = 0; i < M; i++) {
            if (min < gate[i][0]) min = gate[i][0];
            if (max > gate[i][1]) max = gate[i][1];

            if (min > max) {
                System.out.println(0);
                return;
            }
        }
        System.out.println(max - min + 1);
    }
}

import java.util.Scanner;

public class Main {
  public static final void main(String[] args) {
    Rectangle rectangle;
    Circle circle;

    try (Scanner scanner = new Scanner(System.in)) {
      int width = scanner.nextInt();
      int height = scanner.nextInt();
      rectangle = new RectangleImpl(width, height);
      int x = scanner.nextInt();
      int y = scanner.nextInt();
      int center = scanner.nextInt();
      circle = new CircleImpl(x, y, center);
    } catch (Exception e) {
      return;
    }
    if (rectangle.isInCircle(circle)) {
      System.out.println("Yes");
    } else {
      System.out.println("No");
    }
  }
}

interface Rectangle {
  boolean isInCircle(Circle circle);
}

final class RectangleImpl implements Rectangle {

  private final int width;
  private final int height;

  RectangleImpl(int width, int height) {
    this.width = width;
    this.height = height;
  }

  @Override
  public boolean isInCircle(Circle circle) {
    if (circle.getX() - circle.getCenter() < 0) {
      return false;
    }

    if (circle.getX() + circle.getCenter() > width) {
      return false;
    }

    if (circle.getY() - circle.getCenter() < 0) {
      return false;
    }

    if (circle.getY() + circle.getCenter() > height) {
      return false;
    }
    return true;
  }
}

interface Circle {
  int getX();

  int getY();

  int getCenter();
}

final class CircleImpl implements Circle {
  private final int x;
  private final int y;
  private final int center;


  CircleImpl(int x, int y, int center) {
    this.x = x;
    this.y = y;
    this.center = center;
  }

  @Override
  public int getX() {
    return x;
  }

  @Override
  public int getY() {
    return y;
  }

  @Override
  public int getCenter() {
    return center;
  }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader r = new BufferedReader(new InputStreamReader(System.in));
        int N = readInt(r);
        String[] numStrings = r.readLine().split(" ");
        int[] A = new int[N];
        for (int i = 0;i < N;i++) {
            A[i] = Integer.parseInt(numStrings[i]);
        }
//        insertionSort(A, N);
        bubbleSort(A, N);
    }

    public static void insertionSort(int[] A, int N) {
        System.out.println(dump(A, N));
        for (int i = 1;i <= (N - 1);i++) {
            int v = A[i];
            int j = i - 1;
            while (j >= 0 && A[j] > v) {
                A[j + 1] = A[j];
                j--;
            }
            A[j + 1] = v;
            System.out.println(dump(A, N));
        }
    }

    public static void bubbleSort(int[] A, int N) {
        int swapCount = 0;
        boolean flag = true;
        while (flag) {
            flag = false;
            for (int j = N - 1;j >= 1;j--) {
                if (A[j] < A[j - 1]) {
                    swapInt(A, j, j - 1);
                    swapCount++;
                    flag = true;
                }
            }
        }
        System.out.println(dump(A, N));
        System.out.println(swapCount);
    }

    public static void swapInt(int[] A, int j, int k) {
        int v = A[j];
        A[j] = A[k];
        A[k] = v;
    }

    public static String dump(int[] A, int N) {
        StringBuilder builder = new StringBuilder();
        for (int i = 0;i < N;i++) {
            if (i != 0) {
                builder.append(" ");
            }
            builder.append(A[i]);
        }
        return builder.toString();
    }

    public static int readInt(BufferedReader r) throws Exception {
        return Integer.parseInt(r.readLine());
    }
}

