        N = sc.nextInt();
        L = sc.nextInt();
    }

    void solve(PrintWriter out) {
        int min = Integer.MAX_VALUE;
        int sum = 0;
        int[] taste = new int[N];
        int j = 0;
        for (int i = 0; i < N; i++) {
            taste[i] = L + i;
            sum += taste[i];
            if (min > Math.abs(taste[i])) {
                min = Math.abs(taste[i]);
                j = i;
            }      
        }
        out.println(sum - taste[j]);
    }

}

