    }
    public static int HeightLimit(int N, int K, int[] d) {
        if (N <= 0) {
            return 0;
        }
        if (d[N-1] >= K) {
            return 1 + HeightLimit(N-1, K, d);
        }
        return HeightLimit(N-1, K, d);
    }
}

