public class Main {

	static PrintWriter out;
	static InputReader ir;

	static void solve() {
		long a = ir.nextLong();
		long b = ir.nextLong();
		long c = ir.nextLong();
		long d = ir.nextLong();
		out.println(calc(b, c, d) - calc(a - 1, c, d));
	}

	static long calc(long p, long q, long r) {
		long l = q / gcd(q, r) * r;
		return p - p / q - p / r + p / l;
	}

	static long gcd(long a, long b) {
		if (b == 0)
			return a;
		return gcd(b, a % b);
	}

	public static void main(String[] args) {
