      int n = sc.nextInt();
      int a = sc.nextInt();
      int b = sc.nextInt();
      long sum  = 0;

      for(int i = 1; i <= n; i++) {
        if(digitSum(i, a, b))
          sum += i;
      }
      System.out.println(sum);
  }

  private static boolean digitSum(int n, int a, int b) {
    int sum = 0;
    while(n > 0) {
      sum += n % 10;
      n /= 10;
      if(sum > b) return false;
    }

    return sum >= a;
  }
}

