        try(Scanner scanner = new Scanner(System.in)) {
            int N = scanner.nextInt();
            int count = 0;
            boolean flg = true;
            List<Integer> numList = new ArrayList<>();
            scanner.nextLine();
            for (int i = 0; i < N; i++) {
                int j = scanner.nextInt();
                if (j % 2 == 1) {
                    flg = false;
                    break;
                }
                numList.add(j);
