        int s1 = 0, s2 = 1;
        int j = 0;
        for (int i=1; i<=n; i++) {
            int s3 = 0;
            if (j<k && i==a[j]) j++;
            else s3 = (s1 + s2) % m;
            s1 = s2;
            s2 = s3;
        }
        wr(s2);
